package com.autoops.execution.config;import org.springframework.context.annotation.*;import org.springframework.scheduling.annotation.*;import java.util.concurrent.*;@Configuration @EnableAsync public class AsyncConfig{@Bean("executionExecutor")public Executor executionExecutor(){ThreadPoolExecutor e=new ThreadPoolExecutor(1,3,60,TimeUnit.SECONDS,new LinkedBlockingQueue<>(100),new ThreadPoolExecutor.AbortPolicy());return e;}}
